export type ToastState = { message: string; tone: 'success' | 'error' }

const CONTEXT_CATEGORY_COLORS: Record<string, string> = {
  'System prompt': '#4f83ff',
  'System tools': '#8f96a3',
  'Custom agents': '#22a879',
  'Memory files': '#df7900',
  Skills: '#f59e0b',
  Messages: '#8b5cf6',
}

function contextCategoryStyle(name: string): CSSProperties {
  return { '--context-category-color': CONTEXT_CATEGORY_COLORS[name] ?? CONTEXT_CATEGORY_COLORS.Messages } as CSSProperties
}

function contextWindowPercentage(tokens: number, maxTokens: number): number | null {
  return maxTokens > 0 ? Math.max(0, Math.min(100, (tokens / maxTokens) * 100)) : null
}

function contextPercentageLabel(tokens: number, maxTokens: number): string {
  const percentage = contextWindowPercentage(tokens, maxTokens)
  return percentage === null ? '—' : `${Math.round(percentage)}%`
}

function contextCategoryWidth(tokens: number, maxTokens: number): string {
  return `${contextWindowPercentage(tokens, maxTokens) ?? 0}%`
}

class CreateTurnHttpError extends Error {
  constructor(message: string) {
    super(message)
  }
}

async function responseErrorMessage(response: Response): Promise<string> {
  try {
    const body = (await response.clone().json()) as { error?: unknown }
    if (typeof body.error === 'string' && body.error) return body.error
  } catch {}
  const text = await response.text().catch(() => '')
  return text || response.statusText || 'Request failed'
}

function createUserMessageUuid(): string {
  if (crypto.randomUUID) return crypto.randomUUID()
  const bytes = crypto.getRandomValues(new Uint8Array(16))
  bytes[6] = (bytes[6]! & 0x0f) | 0x40
  bytes[8] = (bytes[8]! & 0x3f) | 0x80
  const hex = [...bytes].map((byte) => byte.toString(16).padStart(2, '0')).join('')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}

async function createTurn(projectId: string, existingSessionId: string | null, sessionId: string, text: string, images: ComposerImage[], userMessageUuid: string): Promise<CreateTurnResponse> {
  const path = existingSessionId ? `/api/sessions/${encodeURIComponent(existingSessionId)}/turns` : `/api/projects/${encodeURIComponent(projectId)}/sessions`
  const response = await fetch(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sessionId, ...(text ? { text } : {}), ...(images.length ? { images } : {}), userMessageUuid }),
  })
  if (!response.ok) throw new CreateTurnHttpError(await responseErrorMessage(response))
  return createTurnResponseSchema.parse(await response.json())
}

async function interruptTurn(sessionId: string): Promise<void> {
  const response = await fetch(`/api/sessions/${encodeURIComponent(sessionId)}/interrupt`, { method: 'POST' })
  if (!response.ok) throw new Error(`Interrupt failed: ${response.status}`)
}

type PendingSubmissionBase = { projectId: string; sessionId: string; submissionUuid: string; phase: TurnPhase }
export type PendingSubmission = (PendingSubmissionBase & { kind: 'turn'; turn: TurnSummary }) | (PendingSubmissionBase & { kind: 'slash'; localKey: string; text: string; timestamp: number })

function pendingSubmission(projectId: string, text: string, images: ComposerImage[], sessionId: string, userMessageUuid: string): PendingSubmission {
  const timestamp = new Date().toISOString()
  const base = { projectId, sessionId, submissionUuid: userMessageUuid, phase: 'submitting' as const }
  if (!images.length && isSlashLookingInput(text)) return { ...base, kind: 'slash', localKey: `provisional:${createUserMessageUuid()}`, text, timestamp: Date.parse(timestamp) }
  return {
    ...base,
    kind: 'turn',
    turn: {
      primaryUserUuid: userMessageUuid,
      primaryUserTimestampMs: Date.parse(timestamp),
      entrypoint: 'sdk-ts',
      messages: [
        {
          type: 'user',
          message: { role: 'user', content: buildComposerMessageContent(text, images) },
          parent_tool_use_id: null,
          entrypoint: 'sdk-ts',
          uuid: userMessageUuid,
          session_id: sessionId,
          timestamp,
        },
      ],
    },
  }
}

