const COMPOSER_LOTTIE_HTML = { __html: COMPOSER_LOTTIE_SVG }

function composerLottiePathFingerprint(path: SVGPathElement): string {
  const value = `${path.getAttribute('fill') ?? ''}|${path.getAttribute('d') ?? ''}`
  let hash = 0
  for (let index = 0; index < value.length; index += 1) hash = (Math.imul(hash, 31) + value.charCodeAt(index)) | 0
  return (hash >>> 0).toString(36)
}

function prefersReducedMotion() {
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches
}

export function ComposerLottieButton({ disabled = false }: { disabled?: boolean }) {
  const [reducedMotion, setReducedMotion] = useState(prefersReducedMotion)
  const buttonRef = useRef<HTMLButtonElement | null>(null)
  const pathsRef = useRef<SVGPathElement[]>([])
  const rafRef = useRef(0)

  const show = useCallback((indexes: readonly number[]) => {
    const visible = new Set(indexes)
    pathsRef.current.forEach((path, index) => {
      path.setAttribute('fill-opacity', visible.has(index) ? '1' : '0')
    })
  }, [])

  useEffect(() => {
    const media = window.matchMedia('(prefers-reduced-motion: reduce)')
    const update = () => setReducedMotion(media.matches)
    update()
    media.addEventListener('change', update)
    return () => media.removeEventListener('change', update)
  }, [])

  useEffect(() => {
    if (disabled || reducedMotion) return
    const paths = Array.from(buttonRef.current?.querySelectorAll('path') ?? [])
    const signature = paths.map(composerLottiePathFingerprint).join(',')
    if (signature !== COMPOSER_LOTTIE_PATH_SIGNATURE) {
      console.warn('Composer Lottie SVG path order changed; animation disabled.')
      return
    }
    pathsRef.current = paths
    show(COMPOSER_LOTTIE_IDLE)
    return () => cancelAnimationFrame(rafRef.current)
  }, [disabled, reducedMotion, show])

  function play() {
    cancelAnimationFrame(rafRef.current)
    if (disabled || reducedMotion) return

    const startedAt = performance.now()
    const lastFrameIndex = COMPOSER_LOTTIE_FRAMES.length - 1
    let frameIndex = 0
    let shownFrameIndex = 0
    show(COMPOSER_LOTTIE_FRAMES[0].v)

    function tick(now: number) {
      const elapsed = now - startedAt
      while (frameIndex < lastFrameIndex && COMPOSER_LOTTIE_FRAMES[frameIndex + 1].t <= elapsed) frameIndex += 1
      if (frameIndex !== shownFrameIndex) {
        show(COMPOSER_LOTTIE_FRAMES[frameIndex].v)
        shownFrameIndex = frameIndex
      }
      if (elapsed < COMPOSER_LOTTIE_FRAMES[lastFrameIndex].t) rafRef.current = requestAnimationFrame(tick)
    }

    rafRef.current = requestAnimationFrame(tick)
  }

  if (disabled || reducedMotion) return null
  return (
    <button ref={buttonRef} type="button" className="composer-lottie-button" aria-label="Play composer animation" onClick={play}>
      {/* biome-ignore lint/security/noDangerouslySetInnerHtml: COMPOSER_LOTTIE_SVG is a hard-coded module constant, no user input reaches it */}
      <span className="composer-lottie-art" dangerouslySetInnerHTML={COMPOSER_LOTTIE_HTML} />
    </button>
  )
}

export function TurnComposer({
  projectId,
  selectedSessionId,
  selectedSession,
  activity,
  liveSessionId,
  liveUserMessageUuid,
  latestTurnPhase,
  pendingTurnId,
  setSelectedSessionId,
  setPendingTurn,
  refreshSessionLists,
  onSessionCreated,
  settings,
  sessionRuntime,
  projectDirectoryUnavailable,
  turnOptions,
  externalPermissionMode,
  contextUsage,
  onBeforeSubmit,
  onNotify,
}: {
  projectId: string | null
  selectedSessionId: string | null
  selectedSession: ProjectSessionsResponse['sessions'][number] | null | undefined
  activity: SessionTimelineResponse['activity'] | null
  liveSessionId: string | null
  liveUserMessageUuid: string | null
  latestTurnPhase: TurnPhase | null
  pendingTurnId: string | null
  setSelectedSessionId: (sessionId: string | null) => void
  setPendingTurn: Dispatch<SetStateAction<PendingSubmission | null>>
  refreshSessionLists: (projectId?: string, selectedSessionId?: string | null) => void
  onSessionCreated: (projectId: string, sessionId: string) => void
  settings: AppSettings
  sessionRuntime: SessionRuntimeResponse | null
  projectDirectoryUnavailable: boolean
  turnOptions: SessionTimelineResponse['turnOptions'] | null
  externalPermissionMode: PermissionMode | null
  contextUsage: SessionContextUsage | null
  onBeforeSubmit?: () => void
  onNotify: (toast: ToastState) => void
}) {
  const [inputText, setInputText] = useState('')
  const [images, setImages] = useState<ComposerImage[]>([])
  const imagesRef = useRef<ComposerImage[]>([])
  const [importingImages, setImportingImages] = useState(false)
  const importingImagesRef = useRef(false)
  const imageImportGenerationRef = useRef(0)
  const imageInputRef = useRef<HTMLInputElement | null>(null)
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [interrupting, setInterrupting] = useState(false)
  const inputRef = useRef<HTMLTextAreaElement | null>(null)
  const [unknownSubmission, setUnknownSubmission] = useState<{ userMessageUuid: string; optimisticSessionId: string | null; recoverAt: number } | null>(null)
  const [permissionMode, setPermissionMode] = useState<PermissionMode>(settings.defaultPermissionMode)
  const [permissionMenuOpen, setPermissionMenuOpen] = useState(false)
  const permissionMenuRef = useRef<HTMLDivElement | null>(null)
  const [contextOpen, setContextOpen] = useState(false)
  const contextRef = useRef<HTMLDivElement | null>(null)
  const contextTriggerRef = useRef<HTMLButtonElement | null>(null)
  const [model, setModel] = useState<ModelSelection | DefaultTurnOption>(settings.defaultModel ?? DEFAULT_TURN_OPTION)
  const [effort, setEffort] = useState<EffortLevel | DefaultTurnOption>(settings.defaultEffort ?? DEFAULT_TURN_OPTION)
  const [modelMenuOpen, setModelMenuOpen] = useState(false)
  const [menuModelValue, setMenuModelValue] = useState<ModelSelection | null>(null)
  const [effortMenuPosition, setEffortMenuPosition] = useState<CSSProperties>()
  const modelMenuRef = useRef<HTMLDivElement | null>(null)
  const [addMenuOpen, setAddMenuOpen] = useState(false)
  const [sessionInfoOpen, setSessionInfoOpen] = useState(false)
  const [copyState, setCopyState] = useState<'Copy' | 'Copied' | 'Failed'>('Copy')
  const copyRequestRef = useRef(0)
  const addMenuRef = useRef<HTMLDivElement | null>(null)
  const addTriggerRef = useRef<HTMLButtonElement | null>(null)
  const sessionInfoDialogRef = useRef<HTMLDialogElement | null>(null)
  const composerScopeKey = `${projectId ?? ''}\0${selectedSessionId ?? ''}`
  const queryClient = useQueryClient()
  const composerScopeRef = useRef(composerScopeKey)
  composerScopeRef.current = composerScopeKey
  const composerManuallyChangedRef = useRef(false)
  const manualModelEffortBaselineRef = useRef<string | null>(null)
  const turnOptionsSaveRef = useRef<{ key: string; promise: Promise<void> } | null>(null)
  const [turnOptionsSaveRevision, setTurnOptionsSaveRevision] = useState(0)
  const permissionOptions = PERMISSION_MODE_OPTIONS
  const displayedPermissionMode = projectId ? permissionMode : settings.defaultPermissionMode
  const displayedModel = projectId ? model : (settings.defaultModel ?? DEFAULT_TURN_OPTION)
  const displayedEffort = projectId ? effort : settings.defaultModel != null ? (settings.defaultEffort ?? DEFAULT_TURN_OPTION) : DEFAULT_TURN_OPTION
  const permissionLabel = permissionOptions.find((option) => option.value === displayedPermissionMode)?.label ?? displayedPermissionMode
  const catalogModels = settings.modelCatalog?.models ?? []
  const selectedModel = matchingCatalogModel(catalogModels, displayedModel, settings)
  const menuModel = menuModelValue == null ? undefined : catalogModels.find((item) => item.value === menuModelValue)
  const triggerModelLabel = selectedModel?.displayName || displayedModel
  const triggerEffortLabel = selectedModel?.supportsEffort && displayedEffort !== DEFAULT_TURN_OPTION ? effortLabel(displayedEffort) : null

  // biome-ignore lint/correctness/useExhaustiveDependencies: projectId/selectedSessionId are intentional reset triggers — clear submit error and interrupting state when switching project or session
  useEffect(() => {
    setSubmitError(null)
    setInterrupting(false)
  }, [projectId, selectedSessionId])
  // biome-ignore lint/correctness/useExhaustiveDependencies: composerScopeKey is an intentional reset trigger — cancel in-flight image imports when the composer scope changes
  useEffect(() => {
    imageImportGenerationRef.current += 1
    importingImagesRef.current = false
    setImportingImages(false)
  }, [composerScopeKey])
  useEffect(() => {
    if (interrupting && latestTurnPhase === 'settled') setInterrupting(false)
  }, [interrupting, latestTurnPhase])
  useEffect(() => {
    if (!unknownSubmission) return
    if (pendingTurnId !== unknownSubmission.userMessageUuid) {
      setInputText('')
      imagesRef.current = []
      setImages([])
      setUnknownSubmission(null)
      return
    }
    const timer = window.setTimeout(
      () => {
        setPendingTurn((turn) => (turn?.submissionUuid === unknownSubmission.userMessageUuid ? null : turn))
        if (unknownSubmission.optimisticSessionId === selectedSessionId) setSelectedSessionId(null)
        setUnknownSubmission(null)
      },
      Math.max(0, unknownSubmission.recoverAt - Date.now()),
    )
    return () => window.clearTimeout(timer)
  }, [pendingTurnId, selectedSessionId, setPendingTurn, setSelectedSessionId, unknownSubmission])
  // biome-ignore lint/correctness/useExhaustiveDependencies: composerScopeKey is an intentional reset trigger — reset manual-change tracking and close menus when the composer scope changes
  useEffect(() => {
    composerManuallyChangedRef.current = false
    manualModelEffortBaselineRef.current = null
    setAddMenuOpen(false)
    setSessionInfoOpen(false)
    setContextOpen(false)
  }, [composerScopeKey])
  // biome-ignore lint/correctness/useExhaustiveDependencies: composerScopeKey and turnOptionsSaveRevision are intentional re-run triggers — re-derive model/effort/permission defaults when the scope changes or a turn-options save settles
  useEffect(() => {
    if (composerManuallyChangedRef.current) {
      const modelEffort = JSON.stringify([turnOptions?.model ?? null, turnOptions?.effort ?? null])
      if (!selectedSessionId || modelEffort === manualModelEffortBaselineRef.current) return
      composerManuallyChangedRef.current = false
      manualModelEffortBaselineRef.current = null
    }
    if (selectedSessionId && !turnOptions) return
    const nextModel = selectedSessionId && turnOptions?.model != null ? turnOptions.model : (settings.defaultModel ?? DEFAULT_TURN_OPTION)
    const nextEffort =
      selectedSessionId && turnOptions?.model != null
        ? (turnOptions.effort ?? DEFAULT_TURN_OPTION)
        : settings.defaultModel != null
          ? (settings.defaultEffort ?? DEFAULT_TURN_OPTION)
          : DEFAULT_TURN_OPTION
    setPermissionMode(selectedSessionId ? (turnOptions?.permissionMode ?? settings.defaultPermissionMode) : settings.defaultPermissionMode)
    setModel(nextModel)
    setEffort(nextEffort)
  }, [composerScopeKey, selectedSessionId, turnOptions, settings.defaultPermissionMode, settings.defaultModel, settings.defaultEffort, turnOptionsSaveRevision])
  useEffect(() => {
    if (externalPermissionMode) setPermissionMode(externalPermissionMode)
  }, [externalPermissionMode])
  // biome-ignore lint/correctness/useExhaustiveDependencies: inputText is an intentional trigger — re-measure and auto-grow the textarea height when its content changes
  useEffect(() => {
    const input = inputRef.current
    if (!input) return
    input.style.height = 'auto'
    input.style.height = `${Math.min(input.scrollHeight, 112)}px`
  }, [inputText])
  useEffect(() => {
    if (!permissionMenuOpen && !modelMenuOpen && !contextOpen && !addMenuOpen) return
    function closeOnOutsidePointer(event: globalThis.PointerEvent) {
      const target = event.target as Node
      if (permissionMenuRef.current?.contains(target) || modelMenuRef.current?.contains(target) || contextRef.current?.contains(target) || addMenuRef.current?.contains(target)) return
      setPermissionMenuOpen(false)
      setModelMenuOpen(false)
      setContextOpen(false)
      setAddMenuOpen(false)
    }
    function closeOnEscape(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        setPermissionMenuOpen(false)
        setModelMenuOpen(false)
        if (contextOpen) contextTriggerRef.current?.focus()
        if (addMenuOpen) addTriggerRef.current?.focus()
        setContextOpen(false)
        setAddMenuOpen(false)
      }
    }
    document.addEventListener('pointerdown', closeOnOutsidePointer)
    document.addEventListener('keydown', closeOnEscape)
    return () => {
      document.removeEventListener('pointerdown', closeOnOutsidePointer)
      document.removeEventListener('keydown', closeOnEscape)
    }
  }, [permissionMenuOpen, modelMenuOpen, contextOpen, addMenuOpen])

  const externallyOwned = activity?.owner === 'external' || (!activity && selectedSession?.occupiedBy === 'external')
  const composerBlocked = composerSubmitBlocked({ externallyOwned, projectDirectoryUnavailable })
  const projectRequired = !projectId
  const newTurnBlocked = composerBlocked || (activity ? activity.owner === 'cotta' && activity.phase !== 'idle' && activity.phase !== 'background' : composerSessionBusy(selectedSession))
  const submitState: SubmitState = submitStateFor({ submitting, stopping: interrupting, latestPhase: latestTurnPhase })
  const submissionFrozen = submitting || pendingTurnId !== null || unknownSubmission !== null
  const draftFrozen = importingImages || submissionFrozen
  const imageInputBlocked = composerBlocked || draftFrozen
  const sessionInfoResult = sessionRuntime?.projectId === projectId && sessionRuntime.sessionId === selectedSessionId ? sessionRuntime.initializationResult : null
  const sessionInfoBlocked = sessionInfoResult == null
  const sessionInfoText = sessionInfoOpen ? JSON.stringify(sessionInfoResult, null, 2) : ''

  useEffect(() => {
    const dialog = sessionInfoDialogRef.current
    if (!dialog) return
    if (sessionInfoOpen && !sessionInfoBlocked) dialog.showModal()
    else if (dialog.open) dialog.close()
    if (sessionInfoBlocked) setSessionInfoOpen(false)
  }, [sessionInfoBlocked, sessionInfoOpen])
  useEffect(() => {
    if (addMenuOpen) addMenuRef.current?.querySelector<HTMLButtonElement>('[role="menuitem"]:not(:disabled)')?.focus()
  }, [addMenuOpen])

  async function addImages(files: FileList | File[]) {
    if (importingImagesRef.current || submitting || pendingTurnId || unknownSubmission) {
      onNotify({ message: 'Wait for the current image import or submission to finish.', tone: 'error' })
      return
    }
    const batch = Array.from(files)
    if (!batch.length) return
    if (imagesRef.current.length + batch.length > COMPOSER_IMAGES_MAX_COUNT) {
      onNotify({ message: `You can import up to ${COMPOSER_IMAGES_MAX_COUNT} images at once.`, tone: 'error' })
      return
    }
    if (batch.some((file) => file.size > COMPOSER_IMAGE_MAX_BYTES)) {
      onNotify({ message: 'Each image must be 5 MiB or smaller.', tone: 'error' })
      return
    }
    const existingBytes = imagesRef.current.reduce((total, image) => {
      const inspected = inspectComposerImage(image)
      return total + ('error' in inspected ? 0 : inspected.byteLength)
    }, 0)
    if (existingBytes + batch.reduce((total, file) => total + file.size, 0) > COMPOSER_IMAGES_MAX_BYTES) {
      onNotify({ message: 'Images must total 20 MiB or less.', tone: 'error' })
      return
    }
    const scope = composerScopeKey
    const generation = imageImportGenerationRef.current
    importingImagesRef.current = true
    setImportingImages(true)
    try {
      if (typeof createImageBitmap !== 'function') throw new Error('Image decoding is unavailable in this browser.')
      const results = await Promise.allSettled(
        batch.map(async (file) => {
          const bitmap = await createImageBitmap(file).catch(() => null)
          if (!bitmap) throw new Error('Browser could not decode an image.')
          bitmap.close()
          const dataUrl = await new Promise<string>((resolve, reject) => {
            const reader = new FileReader()
            reader.onerror = () => reject(new Error('Browser could not read an image.'))
            reader.onload = () => (typeof reader.result === 'string' ? resolve(reader.result) : reject(new Error('Browser could not read an image.')))
            reader.readAsDataURL(file)
          })
          const data = dataUrl.slice(dataUrl.indexOf(',') + 1)
          const inspected = inspectComposerImage({ mediaType: file.type, data })
          if ('error' in inspected) throw new Error(inspected.error)
          return { mediaType: inspected.mediaType, data }
        }),
      )
      if (composerScopeRef.current !== scope || imageImportGenerationRef.current !== generation) return
      const failed = results.filter((result): result is PromiseRejectedResult => result.status === 'rejected')
      if (failed.length) {
        results.forEach((result, index) => {
          if (result.status === 'rejected') onNotify({ message: `${batch[index]?.name || 'Image'}: ${result.reason instanceof Error ? result.reason.message : String(result.reason)}`, tone: 'error' })
        })
        return
      }
      const imported = results.map((result) => (result as PromiseFulfilledResult<ComposerImage>).value)
      const next = [...imagesRef.current]
      const keys = new Set(next.map((image) => `${image.mediaType}:${image.data}`))
      let totalBytes = next.reduce((total, image) => {
        const inspected = inspectComposerImage(image)
        return total + ('error' in inspected ? 0 : inspected.byteLength)
      }, 0)
      imported.forEach((image) => {
        const key = `${image.mediaType}:${image.data}`
        const inspected = inspectComposerImage(image)
        if (keys.has(key)) return
        if (next.length >= COMPOSER_IMAGES_MAX_COUNT || 'error' in inspected || totalBytes + inspected.byteLength > COMPOSER_IMAGES_MAX_BYTES) {
          onNotify({ message: next.length >= COMPOSER_IMAGES_MAX_COUNT ? `You can attach up to ${COMPOSER_IMAGES_MAX_COUNT} images.` : 'Images must total 20 MiB or less.', tone: 'error' })
          return
        }
        keys.add(key)
        totalBytes += inspected.byteLength
        next.push(image)
      })
      imagesRef.current = next
      setImages(next)
    } catch (error) {
      if (composerScopeRef.current === scope && imageImportGenerationRef.current === generation) onNotify({ message: error instanceof Error ? error.message : String(error), tone: 'error' })
    } finally {
      if (composerScopeRef.current === scope && imageImportGenerationRef.current === generation) {
        importingImagesRef.current = false
        setImportingImages(false)
      }
    }
  }

  function removeImage(index: number) {
    if (draftFrozen) return
    const next = imagesRef.current.filter((_, currentIndex) => currentIndex !== index)
    imagesRef.current = next
    setImages(next)
    setSubmitError(null)
  }

  async function submitTurn() {
    if (!projectId || importingImages || submissionFrozen || interrupting || (!inputText.trim() && !images.length) || submitState !== 'ready' || newTurnBlocked) return
    if (images.length && isSlashLookingInput(inputText)) {
      onNotify({ message: 'Slash commands do not support images.', tone: 'error' })
      return
    }
    onBeforeSubmit?.()
    const targetProjectId = projectId
    const submitScope = composerScopeKey
    const text = inputText.trim()
    const submittedImages = images
    const userMessageUuid = createUserMessageUuid()
    const existingSessionId = selectedSessionId
    const targetSessionId = existingSessionId ?? createUserMessageUuid()
    setSubmitting(true)
    setSubmitError(null)
    setPendingTurn(pendingSubmission(targetProjectId, text, submittedImages, targetSessionId, userMessageUuid))
    try {
      const effectiveEffort = selectedModel?.supportsEffort ? effort : DEFAULT_TURN_OPTION
      if (existingSessionId) {
        const save = turnOptionsSaveRef.current
        if (save?.key === existingSessionId) await save.promise
      } else if (composerManuallyChangedRef.current) await saveTurnOptions(targetSessionId, { permissionMode, model, effort: effectiveEffort === DEFAULT_TURN_OPTION ? null : effectiveEffort })
      const response = await createTurn(targetProjectId, existingSessionId, targetSessionId, text, submittedImages, userMessageUuid)
      setInputText('')
      imagesRef.current = []
      setImages([])
      const submittedInCurrentScope = composerScopeRef.current === submitScope
      setPendingTurn((current) => (current?.submissionUuid === userMessageUuid ? (submittedInCurrentScope ? { ...current, phase: 'submitted' } : null) : current))
      if (submittedInCurrentScope && !existingSessionId) onSessionCreated(response.projectId, response.sessionId)
      void refreshProjects(response.projectId)
      refreshSessionLists(response.projectId, response.sessionId)
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      if (error instanceof CreateTurnHttpError) {
        setPendingTurn((current) => (current?.submissionUuid === userMessageUuid ? null : current))
        if (composerScopeRef.current === submitScope && !existingSessionId) setSelectedSessionId(null)
      } else {
        setUnknownSubmission({
          userMessageUuid,
          optimisticSessionId: !existingSessionId ? targetSessionId : null,
          recoverAt: Date.now() + UNKNOWN_SUBMISSION_RECOVERY_MS,
        })
        if (composerScopeRef.current === submitScope) setSubmitError(`Submission status unknown. Waiting for the timeline to confirm it. ${message}`)
      }
      if (composerScopeRef.current === submitScope) onNotify({ message, tone: 'error' })
      refreshSessionLists(targetProjectId)
    } finally {
      setSubmitting(false)
    }
  }

  async function stopLiveTurn() {
    if (!projectId || !liveSessionId || !liveUserMessageUuid || submitState !== 'busy') return
    setInterrupting(true)
    setSubmitError(null)
    try {
      await interruptTurn(liveSessionId)
    } catch (error) {
      setSubmitError(error instanceof Error ? error.message : String(error))
      setInterrupting(false)
    }
  }

  function saveCurrentTurnOptions(update: TurnOptionsUpdateRequest, targetSessionId = selectedSessionId) {
    if (!targetSessionId) return
    const key = targetSessionId
    const scope = composerScopeKey
    const save = (turnOptionsSaveRef.current?.key === key ? turnOptionsSaveRef.current.promise.catch(() => {}) : Promise.resolve()).then(() => saveTurnOptions(targetSessionId, update))
    turnOptionsSaveRef.current = { key, promise: save }
    void save.then(
      async () => {
        if (turnOptionsSaveRef.current?.promise !== save) return
        let refreshed = true
        try {
          await queryClient.invalidateQueries({ queryKey: sessionQueryKeys.sessionTimeline(targetSessionId, null).slice(0, 2) }, { throwOnError: true })
        } catch {
          refreshed = false
        }
        if (turnOptionsSaveRef.current?.promise !== save) return
        turnOptionsSaveRef.current = null
        if (composerScopeRef.current !== scope || !refreshed) return
        composerManuallyChangedRef.current = false
        manualModelEffortBaselineRef.current = null
        setSubmitError(null)
        setTurnOptionsSaveRevision((revision) => revision + 1)
      },
      (error) => {
        if (turnOptionsSaveRef.current?.promise !== save) return
        turnOptionsSaveRef.current = null
        if (composerScopeRef.current !== scope) return
        composerManuallyChangedRef.current = false
        manualModelEffortBaselineRef.current = null
        setTurnOptionsSaveRevision((revision) => revision + 1)
        setSubmitError(error instanceof Error ? error.message : String(error))
      },
    )
  }

  function markComposerManualChange() {
    composerManuallyChangedRef.current = true
    manualModelEffortBaselineRef.current = JSON.stringify([turnOptions?.model ?? null, turnOptions?.effort ?? null])
  }

  function toggleModelMenu() {
    setPermissionMenuOpen(false)
    setContextOpen(false)
    setAddMenuOpen(false)
    setMenuModelValue(null)
    setModelMenuOpen((open) => !open)
  }

  function showEffortMenu(option: ModelCatalogItem, target: HTMLElement) {
    const menu = modelMenuRef.current?.querySelector('.model-effort-menu')
    if (!(menu instanceof HTMLElement)) return
    const itemRect = target.getBoundingClientRect()
    const menuRect = menu.getBoundingClientRect()
    const effortCount = option.supportedEffortLevels?.length ?? 0
    const effortMenuHeight = Math.min(220, effortCount * 38 + 16)
    const alignedTop = itemRect.top - menuRect.top
    const clippingBottom = menu.closest('.workspace-main-panel')?.getBoundingClientRect().bottom ?? window.innerHeight
    const maxTop = Math.min(window.innerHeight, clippingBottom) - menuRect.top - effortMenuHeight - 8
    setMenuModelValue(option.value)
    setEffortMenuPosition({ top: Math.max(8, Math.min(alignedTop, maxTop)) })
  }

  function chooseModel(option: ModelCatalogItem) {
    const nextEffort = option.supportsEffort && option.supportedEffortLevels?.includes('medium') ? 'medium' : null
    markComposerManualChange()
    setModel(option.value)
    setEffort(nextEffort ?? DEFAULT_TURN_OPTION)
    setModelMenuOpen(false)
    saveCurrentTurnOptions({ model: option.value, effort: nextEffort })
  }

  function chooseEffort(option: ModelCatalogItem, nextEffort: EffortLevel) {
    markComposerManualChange()
    setModel(option.value)
    setEffort(nextEffort)
    setModelMenuOpen(false)
    saveCurrentTurnOptions({ model: option.value, effort: nextEffort })
  }

  const actionMode = composerActionMode({ submitState, canStop: liveUserMessageUuid !== null && activity?.owner !== 'external' })
  const controlLabel = composerControlLabel({ projectDirectoryUnavailable, externallyOwned })
  const contextPercentage = contextUsage ? contextWindowPercentage(contextUsage.totalTokens, contextUsage.maxTokens) : null
  const contextAutoCompactPercentage = contextUsage?.autoCompactThreshold == null ? null : contextWindowPercentage(contextUsage.autoCompactThreshold, contextUsage.maxTokens)
  const contextLabel = contextPercentage === null ? 'Context usage unavailable' : `Context usage: ${Math.round(contextPercentage)}%`
  const contextUsageModel = contextUsage ? catalogModels.find((item) => item.value === contextUsage.model || item.resolvedModel === contextUsage.model) : undefined
  const contextUsageModelLabel = contextUsageModel?.displayName || contextUsage?.model || 'Unknown'
  const contextUsedTokens = (contextUsage?.categories ?? []).filter((category) => category.kind === 'used').reduce((total, category) => total + category.tokens, 0)
  const contextFreeSpaceTokens = contextUsage?.categories.find((category) => category.kind === 'free')?.tokens ?? null
  const contextBreakdownCategories = (contextUsage?.categories ?? []).filter((category) => category.kind === 'used' && category.tokens > 0)

  function toggleContext() {
    setPermissionMenuOpen(false)
    setModelMenuOpen(false)
    setAddMenuOpen(false)
    setContextOpen((open) => !open)
  }

  function closeSessionInfo() {
    copyRequestRef.current += 1
    setSessionInfoOpen(false)
    setCopyState('Copy')
    addTriggerRef.current?.focus()
  }

  return (
    <section className="composer-card composer-card-bottom">
      <form
        className="turn-form"
        onSubmit={(event) => {
          event.preventDefault()
          void submitTurn()
        }}
      >
        {submitError ? <div className="panel error">{submitError}</div> : null}
        {/* biome-ignore lint/a11y/noStaticElementInteractions lint/a11y/useKeyWithClickEvents: click-anywhere convenience that focuses the inner textarea, which is already keyboard-reachable */}
        <div
          className={`turn-composer${composerBlocked ? ' turn-composer-disabled' : ''}`}
          onClick={(event) => {
            if (composerBlocked || (event.target as HTMLElement).closest('button, textarea, select, .permission-mode-menu, .model-effort-menu')) return
            inputRef.current?.focus()
          }}
          onDragOver={(event) => {
            if (event.dataTransfer.types.includes('Files')) event.preventDefault()
          }}
          onDrop={(event) => {
            if (!event.dataTransfer.types.includes('Files')) return
            event.preventDefault()
            if (!composerBlocked) void addImages(event.dataTransfer.files)
          }}
        >
          <textarea
            ref={inputRef}
            value={inputText}
            onChange={(event) => {
              setInputText(event.target.value)
              setSubmitError(null)
            }}
            onPaste={(event) => {
              const files = Array.from(event.clipboardData.files).filter((file) => file.type.startsWith('image/'))
              if (!files.length) return
              if (!event.clipboardData.getData('text')) event.preventDefault()
              void addImages(files)
            }}
            onKeyDown={(event) => {
              if (
                event.key !== 'Enter' ||
                event.shiftKey ||
                event.nativeEvent.isComposing ||
                projectRequired ||
                importingImages ||
                submissionFrozen ||
                submitState !== 'ready' ||
                (!inputText.trim() && !images.length) ||
                newTurnBlocked
              )
                return
              event.preventDefault()
              void submitTurn()
            }}
            placeholder={controlLabel ?? (projectRequired ? 'Select a project, describe a task or ask a question' : 'Describe a task or ask a question')}
            disabled={composerBlocked || draftFrozen}
            rows={2}
          />
          {images.length ? (
            <ul className="composer-image-previews" aria-label="Attached images">
              {images.map((image, index) => (
                <li className="composer-image-preview" key={`${image.mediaType}:${image.data}`}>
                  <img src={`data:${image.mediaType};base64,${image.data}`} alt={`Attachment ${index + 1}`} />
                  <button type="button" aria-label={`Remove image ${index + 1}`} disabled={draftFrozen} onClick={() => removeImage(index)}>
                    ×
                  </button>
                </li>
              ))}
            </ul>
          ) : null}
          <div className="turn-composer-footer">
            <div className="turn-composer-left-actions">
              <div className="permission-mode-picker" ref={addMenuRef}>
                <button
                  ref={addTriggerRef}
                  type="button"
                  className="turn-tool-button"
                  disabled={imageInputBlocked && sessionInfoBlocked}
                  aria-label="Add"
                  aria-haspopup="menu"
                  aria-expanded={addMenuOpen}
                  onClick={() => {
                    setPermissionMenuOpen(false)
                    setModelMenuOpen(false)
                    setContextOpen(false)
                    setAddMenuOpen((open) => !open)
                  }}
                >
                  <ComposerIcon name="add" />
                </button>
                {addMenuOpen ? (
                  <div
                    className="permission-mode-menu"
                    role="menu"
                    aria-label="Add"
                    onKeyDown={(event) => {
                      if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return
                      event.preventDefault()
                      const items = Array.from(event.currentTarget.querySelectorAll<HTMLButtonElement>('button:not(:disabled)'))
                      const index = items.indexOf(document.activeElement as HTMLButtonElement)
                      items[(index + (event.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length]?.focus()
                    }}
                  >
                    <button
                      type="button"
                      role="menuitem"
                      className="permission-mode-option"
                      disabled={imageInputBlocked}
                      onClick={() => {
                        setAddMenuOpen(false)
                        imageInputRef.current?.click()
                      }}
                    >
                      Upload images
                    </button>
                    <button
                      type="button"
                      role="menuitem"
                      className="permission-mode-option"
                      disabled={sessionInfoBlocked}
                      onClick={() => {
                        setAddMenuOpen(false)
                        setSessionInfoOpen(true)
                      }}
                    >
                      Session info
                    </button>
                  </div>
                ) : null}
                <input
                  ref={imageInputRef}
                  className="composer-image-input"
                  type="file"
                  accept="image/png,image/jpeg,image/gif,image/webp"
                  multiple
                  aria-label="Add image files"
                  disabled={imageInputBlocked}
                  onChange={(event) => {
                    void addImages(event.currentTarget.files ?? [])
                    event.currentTarget.value = ''
                  }}
                />
              </div>
              <div className="model-effort-picker" ref={modelMenuRef}>
                <button
                  type="button"
                  className="model-effort-trigger"
                  aria-haspopup="menu"
                  aria-expanded={modelMenuOpen}
                  aria-label={`Model ${triggerModelLabel}${triggerEffortLabel ? `, effort ${triggerEffortLabel}` : ''}`}
                  title={`${triggerModelLabel}${triggerEffortLabel ? ` / ${triggerEffortLabel}` : ''}`}
                  onClick={toggleModelMenu}
                  disabled={composerBlocked || projectRequired || draftFrozen}
                >
                  <span className="model-effort-trigger-icon" aria-hidden="true">
                    <ModelIcon value={selectedModel?.value ?? displayedModel} />
                  </span>
                  <span className="model-effort-trigger-copy">
                    <span className="model-effort-trigger-model">{triggerModelLabel}</span>
                    {triggerEffortLabel ? <span className="model-effort-trigger-effort">{triggerEffortLabel}</span> : null}
                  </span>
                </button>
                {modelMenuOpen ? (
                  <div className="model-effort-menu" role="menu" aria-label="Model and effort">
                    {/* biome-ignore lint/a11y/useSemanticElements: menu item group inside role="menu"; <fieldset> adds UA border/padding/min-width */}
                    <div className="model-effort-models" role="group" aria-label="Models">
                      {catalogModels.map((option) => {
                        const active = menuModel?.value === option.value
                        const selected = selectedModel?.value === option.value
                        return (
                          <button
                            key={option.value}
                            type="button"
                            className="model-effort-option"
                            role="menuitem"
                            aria-current={active}
                            onMouseEnter={(event) => showEffortMenu(option, event.currentTarget)}
                            onFocus={(event) => showEffortMenu(option, event.currentTarget)}
                            onClick={(event) => (option.supportsEffort && option.supportedEffortLevels?.length ? showEffortMenu(option, event.currentTarget) : chooseModel(option))}
                          >
                            <span className="model-effort-option-icon" aria-hidden="true">
                              <ModelIcon value={option.value} />
                            </span>
                            <span className="model-effort-option-title">{option.displayName || option.value}</span>
                            {selected ? (
                              <span className="model-effort-option-check" aria-hidden="true">
                                ✓
                              </span>
                            ) : null}
                          </button>
                        )
                      })}
                    </div>
                    {menuModel?.supportsEffort && menuModel.supportedEffortLevels?.length ? (
                      // biome-ignore lint/a11y/useSemanticElements: menu item group inside role="menu"; <fieldset> adds UA border/padding/min-width
                      <div className="model-effort-efforts" style={effortMenuPosition} role="group" aria-label={`${menuModel.displayName || menuModel.value} efforts`}>
                        {supportedEffortLevels(menuModel).map((level) => {
                          const selected = selectedModel?.value === menuModel.value && effort === level
                          return (
                            <button
                              key={`${menuModel.value}:${level}`}
                              type="button"
                              className="model-effort-option model-effort-option-compact"
                              role="menuitemradio"
                              aria-checked={selected}
                              onClick={() => chooseEffort(menuModel, level)}
                            >
                              <span className="model-effort-option-title">{effortLabel(level)}</span>
                              {selected ? (
                                <span className="model-effort-option-check" aria-hidden="true">
                                  ✓
                                </span>
                              ) : null}
                            </button>
                          )
                        })}
                      </div>
                    ) : null}
                  </div>
                ) : null}
              </div>
              <div className="permission-mode-picker" ref={permissionMenuRef}>
                <button
                  type="button"
                  className="turn-tool-button permission-mode-trigger"
                  aria-haspopup="menu"
                  aria-expanded={permissionMenuOpen}
                  aria-label={`Permission mode: ${permissionLabel}`}
                  onClick={() => {
                    if (!composerBlocked) {
                      setModelMenuOpen(false)
                      setContextOpen(false)
                      setAddMenuOpen(false)
                      setPermissionMenuOpen((open) => !open)
                    }
                  }}
                  disabled={composerBlocked || projectRequired || draftFrozen}
                >
                  <ComposerIcon name="shield" />
                  <span>{permissionLabel}</span>
                </button>
                {permissionMenuOpen ? (
                  <div className="permission-mode-menu" role="menu" aria-label="Permission mode">
                    {permissionOptions.map((option) => (
                      <button
                        key={option.value}
                        type="button"
                        className="permission-mode-option"
                        role="menuitemradio"
                        aria-checked={permissionMode === option.value}
                        onClick={() => {
                          markComposerManualChange()
                          setPermissionMode(option.value)
                          setPermissionMenuOpen(false)
                          saveCurrentTurnOptions({ permissionMode: option.value })
                        }}
                      >
                        <span className="permission-mode-option-copy">
                          <span className="permission-mode-option-title">{option.label}</span>
                          <span className="permission-mode-option-description">{option.description}</span>
                        </span>
                      </button>
                    ))}
                  </div>
                ) : null}
              </div>
            </div>
            <div className="turn-composer-submit-actions">
              {contextUsage ? (
                <div className="composer-context-control" ref={contextRef}>
                  <button
                    ref={contextTriggerRef}
                    className="composer-context-ring"
                    type="button"
                    aria-haspopup="dialog"
                    aria-expanded={contextOpen}
                    aria-controls="composer-context-popover"
                    aria-label={contextLabel}
                    title={contextLabel}
                    data-has-auto-compact={contextAutoCompactPercentage === null ? undefined : 'true'}
                    style={
                      {
                        '--context-usage': `${contextPercentage ?? 0}%`,
                        '--context-auto-compact': `${contextAutoCompactPercentage ?? 0}%`,
                      } as CSSProperties
                    }
                    onClick={toggleContext}
                    disabled={!projectId || !selectedSessionId || submissionFrozen}
                  >
                    {contextPercentage === null ? null : <span aria-hidden="true">{Math.round(contextPercentage)}%</span>}
                  </button>
                  {contextOpen ? (
                    <section className="composer-context-popover" id="composer-context-popover" role="dialog" aria-label="Context usage details">
                      <header className="composer-context-popover-header">
                        <div>
                          <strong>Context usage</strong>
                          <span>Model: {contextUsageModelLabel}</span>
                        </div>
                        <span className="composer-context-popover-percent">{contextPercentage === null ? '—' : `${Math.round(contextPercentage)}%`}</span>
                      </header>
                      {contextUsage ? (
                        <div className="composer-context-categories">
                          <div className="composer-context-stack-meter" aria-hidden="true">
                            <div className="composer-context-stack">
                              {contextBreakdownCategories.map((category) =>
                                category.tokens > 0 ? (
                                  <span
                                    key={category.name}
                                    className="composer-context-stack-segment"
                                    style={{ ...contextCategoryStyle(category.name), width: contextCategoryWidth(category.tokens, contextUsage.maxTokens) }}
                                  />
                                ) : null,
                              )}
                            </div>
                            {contextAutoCompactPercentage === null ? null : (
                              <span className="composer-context-auto-compact-marker" style={{ left: contextCategoryWidth(contextUsage.autoCompactThreshold ?? 0, contextUsage.maxTokens) }} />
                            )}
                          </div>
                          <div className="composer-context-breakdown">
                            {contextBreakdownCategories.map((category) => (
                              <div className="composer-context-breakdown-row" key={category.name}>
                                <span className="composer-context-breakdown-label">
                                  {category.name}
                                  {'isDeferred' in category && category.isDeferred ? ' (deferred)' : ''}
                                </span>
                                <span className="composer-context-breakdown-track" aria-hidden="true">
                                  <span
                                    className="composer-context-breakdown-fill"
                                    style={{ ...contextCategoryStyle(category.name), width: contextCategoryWidth(category.tokens, contextUsage.maxTokens) }}
                                  />
                                </span>
                                <strong className="composer-context-breakdown-value">{category.tokens.toLocaleString()}</strong>
                                <span className="composer-context-breakdown-percent">{contextPercentageLabel(category.tokens, contextUsage.maxTokens)}</span>
                              </div>
                            ))}
                          </div>
                          <dl className="composer-context-summary">
                            <div>
                              <dt>Total used</dt>
                              <dd>{contextUsedTokens.toLocaleString()}</dd>
                              <span className="composer-context-breakdown-percent">{contextPercentageLabel(contextUsedTokens, contextUsage.maxTokens)}</span>
                            </div>
                            <div>
                              <dt>Free space</dt>
                              <dd>{contextFreeSpaceTokens === null ? '—' : contextFreeSpaceTokens.toLocaleString()}</dd>
                              <span className="composer-context-breakdown-percent">
                                {contextFreeSpaceTokens === null ? '—' : contextPercentageLabel(contextFreeSpaceTokens, contextUsage.maxTokens)}
                              </span>
                            </div>
                            <div>
                              <dt>Auto-compact</dt>
                              <dd>{contextUsage.autoCompactThreshold === null ? '—' : contextUsage.autoCompactThreshold.toLocaleString()}</dd>
                              <span className="composer-context-breakdown-percent">
                                {contextUsage.autoCompactThreshold === null ? '—' : contextPercentageLabel(contextUsage.autoCompactThreshold, contextUsage.maxTokens)}
                              </span>
                            </div>
                            <div>
                              <dt>Maximum</dt>
                              <dd>{contextUsage.maxTokens.toLocaleString()}</dd>
                              <span className="composer-context-breakdown-percent">{contextPercentageLabel(contextUsage.maxTokens, contextUsage.maxTokens)}</span>
                            </div>
                          </dl>
                        </div>
                      ) : (
                        <div className="composer-context-empty">No context data yet.</div>
                      )}
                    </section>
                  ) : null}
                </div>
              ) : null}
              <button
                type={actionMode === 'submit' ? 'submit' : 'button'}
                className="turn-action-button"
                onClick={actionMode === 'stop' ? stopLiveTurn : undefined}
                disabled={
                  projectRequired ||
                  composerBlocked ||
                  actionMode === 'loading' ||
                  (actionMode === 'stop' && !liveUserMessageUuid) ||
                  (actionMode === 'submit' && (draftFrozen || newTurnBlocked || (!inputText.trim() && !images.length)))
                }
                aria-label={interrupting ? 'Interrupting' : actionMode === 'loading' ? 'Submitting' : actionMode === 'stop' ? 'Stop generation' : (controlLabel ?? 'Submit')}
                title={controlLabel ?? undefined}
              >
                {actionMode === 'loading' ? (
                  <span className="turn-spinner" aria-hidden="true" />
                ) : actionMode === 'stop' ? (
                  <span className="turn-stop-icon" aria-hidden="true" />
                ) : composerBlocked || (actionMode === 'submit' && newTurnBlocked) ? (
                  <svg className="turn-blocked-icon" viewBox="0 0 20 20" aria-hidden="true">
                    <circle cx="10" cy="10" r="6.5" />
                    <path d="m5.4 5.4 9.2 9.2" />
                  </svg>
                ) : (
                  '↑'
                )}
              </button>
            </div>
          </div>
        </div>
      </form>
      {/* biome-ignore lint/a11y/useKeyWithClickEvents: backdrop click-to-close; keyboard closes via native dialog Escape (onClose) */}
      <dialog
        ref={sessionInfoDialogRef}
        className="session-search-dialog composer-session-info-dialog"
        aria-labelledby="composer-session-info-title"
        onClick={(event) => {
          if (event.target === event.currentTarget) closeSessionInfo()
        }}
        onClose={closeSessionInfo}
      >
        <div className="session-search-shell">
          <header className="session-search-header">
            <h2 id="composer-session-info-title">Session info</h2>
            <button className="session-search-close" type="button" onClick={closeSessionInfo} aria-label="Close">
              <svg viewBox="0 0 20 20" aria-hidden="true">
                <path d="M5 5 15 15M15 5 5 15" />
              </svg>
            </button>
          </header>
          <div className="composer-session-info-content">
            <button
              type="button"
              onClick={() => {
                const writeText = navigator.clipboard?.writeText
                if (!writeText) return setCopyState('Failed')
                const request = ++copyRequestRef.current
                void writeText.call(navigator.clipboard, sessionInfoText).then(
                  () => request === copyRequestRef.current && setCopyState('Copied'),
                  () => request === copyRequestRef.current && setCopyState('Failed'),
                )
              }}
            >
              {copyState}
            </button>
            <pre>{sessionInfoText}</pre>
          </div>
        </div>
      </dialog>
    </section>
  )
}
